contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint v) public payable {
        uint balanceBefore = address(c).balance;
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdraw(v); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        if (!reverted) {
            assert(address(c).balance <= balanceBefore);
            assert(address(c).balance + v == balanceBefore);
        } else {
            assert(address(c).balance == balanceBefore);
        }
        assert(c.depositsCount() == depositsBefore);
    }
}

